<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityLoginProviderVO;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;

trait UserFederatedIdentityLoginProviderAttributeHolder
{
    protected UserFederatedIdentityLoginProviderVO|TenantLoginProviderRef|null $loginProvider = null;
    protected bool $loginProviderAssigned = false;

    public function getLoginProviderOrCurrent(UserFederatedIdentityLoginProviderVO $loginProvider): UserFederatedIdentityLoginProviderVO
    {
        if ($this->loginProviderAssigned) {
            \assert(null !== $this->loginProvider);
            return UserFederatedIdentityLoginProviderVO::from($this->loginProvider);
        } else {
            return $loginProvider;
        }
    }
    public function loginProviderTryBuildInitial(ConstraintFailList $error): ?UserFederatedIdentityLoginProviderVO
    {
        return  UserFederatedIdentityLoginProviderVO::tryFrom($this->loginProviderAssigned ? $this->loginProvider : null, $error);
    }
    public function loginProvider(UserFederatedIdentityLoginProviderVO|TenantLoginProviderRef $loginProvider): static
    {
        $this->loginProvider = $loginProvider;
        $this->loginProviderAssigned = true;
        return $this;
    }
    public function getLoginProvider(): ?TenantLoginProviderRef
    {
        return $this->loginProvider instanceof UserFederatedIdentityLoginProviderVO ? $this->loginProvider->value() : $this->loginProvider;
    }
    public function isLoginProviderAssigned(): bool
    {
        return $this->loginProviderAssigned;
    }
    public function writeLoginProviderTo(mixed $att): void
    {
        if ($this->loginProviderAssigned) {
            \assert(null !== $this->loginProvider);
            $att->loginProvider($this->loginProvider);
        }
    }
    public function readLoginProviderFrom(mixed $att): void
    {
        if ($att->isLoginProviderAssigned()) {
            $loginProvider = $att->getLoginProvider();
            \assert(null !== $loginProvider);
            $this->loginProvider($loginProvider);
        }
    }
    public function unsetLoginProvider(): static
    {
        $this->loginProviderAssigned = false;
        return $this;
    }
    protected function withDefaultLoginProvider(): void
    {
    }
    protected function withAssertedLoginProviderRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->loginProviderAssigned = $this->loginProviderAssigned) {
            $value->loginProvider = UserFederatedIdentityLoginProviderVO::tryFrom($this->loginProvider, $errorsList);
        }
    }
}
